import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.NpvCl_7q.js";const u=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/index.md","filePath":"contributing/index.md","lastUpdated":1792608207000}'),i={name:"contributing/index.md"};function o(p,e,d,c,r,l){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Thanks for helping out. This page covers how the repo is laid out and how a change gets from your editor to a merged PR. <a href="/nativescript-mason/contributing/building">Building from source</a> and <a href="/nativescript-mason/contributing/testing">Testing</a> have the details.</p><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>crates/</span></span>
<span class="line"><span>  mason-core/         Rust layout engine, built on taffy</span></span>
<span class="line"><span>  mason-c/            C ABI over mason-core (used by iOS and Windows)</span></span>
<span class="line"><span>  mason-ios/          Static library for iOS (libmasonnative.a)</span></span>
<span class="line"><span>  mason-android/      JNI shared library for Android (libmasonnative.so)</span></span>
<span class="line"><span>  mason-windows/      Static library for the Windows component</span></span>
<span class="line"><span>  mason-playground/   Scratch binary for trying the engine from Rust</span></span>
<span class="line"><span></span></span>
<span class="line"><span>packages/nativescript-masonkit/</span></span>
<span class="line"><span>  *.ts                The plugin: elements, style buffer, CSS properties</span></span>
<span class="line"><span>  angular/ vue/ svelte/   Framework entry points</span></span>
<span class="line"><span>  platforms/          Prebuilt native libraries that ship in the npm package</span></span>
<span class="line"><span>    android/            masonkit-release.aar</span></span>
<span class="line"><span>    ios/                Mason.xcframework</span></span>
<span class="line"><span>    windows/            NativeScript.Mason.{dll,winmd} + MSBuild glue</span></span>
<span class="line"><span>  src-native/</span></span>
<span class="line"><span>    mason-android/    Kotlin library (Gradle) that produces the AAR</span></span>
<span class="line"><span>    mason-ios/        Swift framework (Xcode) that produces the xcframework</span></span>
<span class="line"><span>    windows/          C++/WinRT component</span></span>
<span class="line"><span></span></span>
<span class="line"><span>apps/</span></span>
<span class="line"><span>  demo/               Plain NativeScript (XML) demo</span></span>
<span class="line"><span>  demo-angular/  demo-react/  demo-solid/  demo-svelte/  demo-vue/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tools/</span></span>
<span class="line"><span>  scripts/            Build scripts and code generators</span></span>
<span class="line"><span>  testing/            Vitest config and the Node test kit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docs/                 This site (VitePress)</span></span></code></pre></div><p>A few files are worth knowing before you start:</p><ul><li><code>packages/nativescript-masonkit/style.ts</code>: the shared style buffer and every typed style setter.</li><li><code>packages/nativescript-masonkit/properties.ts</code>: CSS property registration on NativeScript&#39;s <code>Style</code>.</li><li><code>packages/nativescript-masonkit/web.ts</code>: the HTML-shaped elements (<code>div</code>, <code>p</code>, <code>h1</code>, ...).</li><li><code>packages/nativescript-masonkit/elements.ts</code>: the element registry every framework integration builds from.</li><li><code>tools/scripts/style-keys/style-keys.schema</code>: the single source for style buffer offsets in every language.</li><li><code>MASON_CONTEXT.md</code> at the repo root: long-form contributor notes, invariants and known gotchas.</li></ul><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><ol><li>Install dependencies from the repo root with <code>npm install</code>. (<code>npm run setup</code> does a clean reinstall, deleting <code>node_modules</code>, <code>dist</code> and <code>package-lock.json</code> first.)</li><li>Make your change. TypeScript edits go in <code>packages/nativescript-masonkit</code>; native edits go in <code>src-native/</code> or <code>crates/</code>.</li><li>Run the fast checks: <code>npm test</code>, plus <code>npm run test:rust</code> if you touched Rust. See <a href="/nativescript-mason/contributing/testing">Testing</a>.</li><li>If you changed native code, rebuild the AAR or xcframework and copy it into <code>platforms/</code>. See <a href="/nativescript-mason/contributing/building">Building from source</a>.</li><li>Rebuild the package and run a demo app on a device or simulator.</li><li>Open a PR against <code>main</code>.</li></ol><p><code>npm start</code> opens an interactive menu (<code>nps</code>) with commands to run, clean and focus each demo.</p><p>A pre-commit hook runs Prettier on staged <code>js</code>, <code>ts</code>, <code>scss</code>, <code>json</code> and <code>html</code> files.</p><div class="tip custom-block"><p class="custom-block-title">Demo apps use the built package</p><p>Every demo except <code>apps/demo</code> depends on <code>dist/packages/nativescript-masonkit</code>, not the source folder. After editing the plugin&#39;s TypeScript, rebuild it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nativescript-masonkit:build.all</span></span></code></pre></div><p>Native library changes need the app to be stopped and run again; livesync does not reload native code.</p></div><h2 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI&quot;">​</a></h2><p>Every PR and push to <code>main</code> runs <code>.github/workflows/pr.yml</code> on a plain Ubuntu runner (no device, no browser):</p><table tabindex="0"><thead><tr><th>Job</th><th>What it checks</th></tr></thead><tbody><tr><td>Generated StyleKeys are up to date</td><td><code>node tools/scripts/style-keys/generate.mjs --check</code></td></tr><tr><td>TypeScript CSS value layer</td><td><code>npm test</code>, <code>npm run test:jsx-types</code>, and a typecheck of the plugin (<code>tsc --noEmit</code>)</td></tr><tr><td>mason-core</td><td><code>cargo fmt --all -- --check</code> and <code>cargo test -p mason-core --all-targets</code></td></tr></tbody></table><p><code>.github/workflows/nightly.yml</code> runs the slower checks once a day (and on demand):</p><table tabindex="0"><thead><tr><th>Job</th><th>What it checks</th></tr></thead><tbody><tr><td>Chromium ground truth is unchanged</td><td><code>npm run gen:webspec -- --check</code> against a real headless Chromium</td></tr><tr><td>Kotlin unit tests</td><td><code>./gradlew :masonkit:testReleaseUnitTest</code></td></tr><tr><td>Swift unit tests</td><td><code>xcodebuild test -scheme Mason</code> on an iOS simulator</td></tr></tbody></table><p>A unit or parsing bug should fail in the PR workflow before it ever reaches a device.</p><h2 id="working-on-these-docs" tabindex="-1">Working on these docs <a class="header-anchor" href="#working-on-these-docs" aria-label="Permalink to &quot;Working on these docs&quot;">​</a></h2><p>The site lives in <code>docs/</code> with its own <code>package.json</code>, separate from the workspace:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # local dev server with hot reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # production build into docs/.vitepress/dist</span></span></code></pre></div><p>Pages are Markdown; the sidebar is in <code>docs/.vitepress/config.mts</code>. Pushes to <code>main</code> that touch <code>docs/</code> deploy the site to GitHub Pages.</p><h2 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;Releases&quot;">​</a></h2><p>Maintainers publish with <code>npm run publish-packages</code>, which prompts for the packages and version to publish.</p>`,23)])])}const k=s(i,[["render",o]]);export{u as __pageData,k as default};
